<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{Auth,DB,Hash};
use Illuminate\Validation\Rule;
use App\Models\User;
use Carbon\Carbon;

class SiteController extends Controller {
 private function center(){return DB::table('centros')->where('nombre_comercial','SELEGAL')->firstOrFail();}
 private function view($page,$data=[]){$c=$this->center();return view('site',array_merge(['page'=>$page,'settings'=>['phone'=>$c->whatsapp ?: $c->telefono,'email'=>$c->email,'address'=>$c->direccion,'show_address'=>$c->mostrar_direccion?'1':'0']],$data));}
 private function requestsQuery(){return DB::table('solicitudes as s')->join('solicitantes as p','p.id','=','s.solicitante_id')->join('materias as m','m.id','=','s.materia_id')->selectRaw("s.id, p.nombre_completo as name, p.telefono as phone, p.email, m.nombre as matter, s.descripcion as description, s.fecha_solicitud as created_at, CASE s.estado WHEN 'PENDIENTE' THEN 'Pendiente' ELSE 'Contactado' END as status");}
 private function appointmentsQuery(){return DB::table('citas as c')->join('solicitudes as s','s.id','=','c.solicitud_id')->join('solicitantes as p','p.id','=','s.solicitante_id')->join('materias as m','m.id','=','s.materia_id')->selectRaw("c.id,c.solicitud_id as request_id,c.fecha as day, TIME_FORMAT(c.hora_inicio,'%H:%i') as time, p.nombre_completo as name,m.nombre as matter, CASE c.estado WHEN 'CANCELADA' THEN 'Cancelada' WHEN 'REAGENDADA' THEN 'Reprogramada' WHEN 'FINALIZADA' THEN 'Finalizada' WHEN 'PENDIENTE' THEN 'Pendiente' ELSE 'Confirmada' END as status");}
 private function members(){return DB::table('equipo')->where('centro_id',$this->center()->id)->selectRaw('id,nombre_completo as name,cargo as role,fotografia as photo,descripcion as description,0 as example');}
 private function reviews(){return DB::table('testimonios')->where('centro_id',$this->center()->id)->selectRaw('id,nombre_cliente as name,contenido as body,visible,0 as example');}
 private function slots(){ $center=$this->center();$hours=DB::table('horarios_atencion')->where('centro_id',$center->id)->where('activo',1)->get();$booked=DB::table('citas')->where('centro_id',$center->id)->where('fecha','>=',today()->toDateString())->where('estado','!=','CANCELADA')->get()->mapWithKeys(fn($a)=>[$a->fecha.'|'.substr($a->hora_inicio,0,5)=>true]);$out=collect();for($n=0;$n<60;$n++){ $day=today()->addDays($n);foreach($hours->where('dia_semana',$day->dayOfWeekIso) as $h){$t=Carbon::parse($day->toDateString().' '.$h->hora_inicio);$end=Carbon::parse($day->toDateString().' '.$h->hora_fin);while($t->copy()->addMinutes($h->duracion_minutos)->lte($end)){ $key=$day->toDateString().'|'.$t->format('H:i');if(!isset($booked[$key]) && $t->isFuture())$out->push((object)['day'=>$day->toDateString(),'time'=>$t->format('H:i')]);$t->addMinutes($h->duracion_minutos);}}}return $out; }
 private function reserve($requestId,$day,$time){$center=$this->center();$date=Carbon::parse($day);$h=DB::table('horarios_atencion')->where('centro_id',$center->id)->where('dia_semana',$date->dayOfWeekIso)->where('activo',1)->get()->first(function($h)use($day,$time){$start=Carbon::parse($day.' '.$h->hora_inicio);$selected=Carbon::parse($day.' '.$time);return $selected->gte($start) && $selected->copy()->addMinutes($h->duracion_minutos)->lte(Carbon::parse($day.' '.$h->hora_fin)) && $start->diffInMinutes($selected)%$h->duracion_minutos===0 && $selected->isFuture();});if(!$h)throw new \RuntimeException('Horario no disponible.');return DB::table('citas')->insertGetId(['solicitud_id'=>$requestId,'centro_id'=>$center->id,'horario_atencion_id'=>$h->id,'fecha'=>$day,'hora_inicio'=>$time,'hora_fin'=>Carbon::parse($day.' '.$time)->addMinutes($h->duracion_minutos)->format('H:i:s'),'estado'=>'CONFIRMADA']);}
 public function home(){return $this->view('home',['members'=>$this->members()->where('visible',1)->get(),'testimonials'=>$this->reviews()->where('visible',1)->get()]);} public function services(){return $this->view('services');} public function process(){return $this->view('process');} public function contact(){return $this->view('contact');} public function requestForm(){return $this->view('request');} public function login(){return $this->view('login');}
 public function team(){return $this->view('team',['members'=>$this->members()->where('visible',1)->get()]);} public function testimonials(){return $this->view('testimonials',['testimonials'=>$this->reviews()->where('visible',1)->get()]);}
 public function requestStore(Request $r){$v=$r->validate(['name'=>'required|string|max:150','phone'=>'required|string|max:20','email'=>'required|email|max:150','matter'=>['required',Rule::in(['Civil','Familiar'])],'description'=>'required|string|max:3000'],['required'=>'Este campo es obligatorio']);$id=DB::transaction(function()use($v){$p=DB::table('solicitantes')->insertGetId(['nombre_completo'=>$v['name'],'telefono'=>$v['phone'],'email'=>$v['email']]);$id=DB::table('solicitudes')->insertGetId(['centro_id'=>$this->center()->id,'solicitante_id'=>$p,'materia_id'=>DB::table('materias')->where('nombre',$v['matter'])->value('id'),'descripcion'=>$v['description']]);DB::table('notificaciones')->insert(['solicitud_id'=>$id,'tipo'=>'NUEVA_SOLICITUD','canal'=>'SISTEMA','mensaje'=>'Nueva solicitud recibida.']);return $id;});$this->notifyRequest($id);$r->session()->put('request_id',$id);return redirect()->route('request.success');}
 private function notifyRequest($id){
  $recipient=$this->center()->email;
  $notice=DB::table('notificaciones')->insertGetId(['solicitud_id'=>$id,'tipo'=>'NUEVA_SOLICITUD','canal'=>'EMAIL','destinatario'=>$recipient,'mensaje'=>'Nueva solicitud disponible en el panel.','estado'=>'PENDIENTE']);
  if(!$recipient || in_array(config('mail.default'),['log','array'],true)) return;
  try { \Illuminate\Support\Facades\Mail::raw("Se ha registrado una nueva solicitud (#{$id}). Ingresa al panel de SELEGAL para revisarla.",function($message) use($recipient){$message->to($recipient)->subject('Nueva solicitud de conciliación - SELEGAL');}); DB::table('notificaciones')->where('id',$notice)->update(['estado'=>'ENVIADA','fecha_envio'=>now()]); }
  catch(\Throwable $e){DB::table('notificaciones')->where('id',$notice)->update(['estado'=>'FALLIDA']);report($e);}
 }
 public function requestSuccess(Request $r){abort_unless($r->session()->has('request_id'),403);return $this->view('success');}
 public function schedule(Request $r){abort_unless($r->session()->has('request_id'),403);$slots=$this->slots()->groupBy('day');return $this->view('schedule',compact('slots'));}
 public function book(Request $r){$id=$r->session()->get('request_id');abort_unless($id,403);$v=$r->validate(['day'=>'required|date|after_or_equal:today','time'=>'required|date_format:H:i']);try{$appointment=DB::transaction(fn()=>$this->reserve($id,$v['day'],$v['time']));}catch(\Illuminate\Database\QueryException|\RuntimeException $e){return back()->withErrors(['day'=>'Este horario ya no está disponible. Elige otro.']);}$r->session()->put('appointment_id',$appointment);$r->session()->forget('request_id');return redirect()->route('booked');}
 public function booked(Request $r){$a=$this->appointmentsQuery()->where('c.id',$r->session()->get('appointment_id'))->first();abort_unless($a,404);return $this->view('booked',compact('a'));}
 public function authenticate(Request $r){$v=$r->validate(['email'=>'required|email','password'=>'required']);if(Auth::attempt($v+['activo'=>1])){$r->session()->regenerate();return redirect()->intended(route('admin.dashboard'));}return back()->withErrors(['email'=>'Credenciales incorrectas.']);}
 public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('home');}
 private function admin($page,$data=[]){return $this->view($page,$data);}
 public function dashboard(){return $this->admin('dashboard',['newCount'=>DB::table('solicitudes')->where('estado','PENDIENTE')->count(),'appointmentCount'=>DB::table('citas')->where('fecha','>=',today())->whereIn('estado',['PENDIENTE','CONFIRMADA','REAGENDADA'])->count(),'recent'=>$this->requestsQuery()->orderByDesc('s.fecha_solicitud')->limit(5)->get()]);}
 public function requests(Request $r){return $this->admin('admin-requests',['items'=>$this->requestsQuery()->orderByDesc('s.fecha_solicitud')->get(),'detail'=>$r->query('ver')?$this->requestsQuery()->where('s.id',$r->query('ver'))->first():null]);}
 public function contacted($id){DB::table('solicitudes')->where('id',$id)->update(['estado'=>'EN_REVISION']);return back()->with('success','Solicitud actualizada');}
 public function appointments(){return $this->admin('admin-appointments',['items'=>$this->appointmentsQuery()->orderByDesc('c.fecha')->get(),'requests'=>$this->requestsQuery()->whereNotExists(function($q){$q->selectRaw('1')->from('citas')->whereColumn('citas.solicitud_id','s.id');})->orderByDesc('s.id')->get(),'slots'=>$this->slots()]);}
 public function adminBook(Request $r){
  $v=$r->validate(['mode'=>['required',Rule::in(['existing','new'])],'request_id'=>['required_if:mode,existing','nullable',Rule::exists('solicitudes','id')->where('centro_id',$this->center()->id)],'name'=>'required_if:mode,new|nullable|string|max:150','phone'=>'required_if:mode,new|nullable|string|max:20','email'=>'required_if:mode,new|nullable|email|max:150','matter'=>['required_if:mode,new','nullable',Rule::in(['Civil','Familiar'])],'description'=>'required_if:mode,new|nullable|string|max:3000','day'=>'required|date|after_or_equal:today','time'=>'required|date_format:H:i'],['required_if'=>'Este campo es obligatorio.','required'=>'Este campo es obligatorio.']);
  try{DB::transaction(function()use($v){if($v['mode']==='new'){$person=DB::table('solicitantes')->insertGetId(['nombre_completo'=>$v['name'],'telefono'=>$v['phone'],'email'=>$v['email']]);$requestId=DB::table('solicitudes')->insertGetId(['centro_id'=>$this->center()->id,'solicitante_id'=>$person,'materia_id'=>DB::table('materias')->where('nombre',$v['matter'])->value('id'),'descripcion'=>$v['description']]);}else{$requestId=$v['request_id'];} $this->reserve($requestId,$v['day'],$v['time']);});}catch(\Illuminate\Database\QueryException|\RuntimeException $e){return back()->withInput()->withErrors(['day'=>'La solicitud ya tiene cita o el horario dejó de estar disponible. Selecciona otro.']);}return redirect()->route('admin.appointments')->with('success','Cita registrada correctamente');
 }
 public function appointmentStatus(Request $r,$id){$v=$r->validate(['status'=>['required',Rule::in(['Pendiente','Confirmada','Cancelada','Reprogramada','Finalizada'])],'new_slot'=>'nullable|string']);try{DB::transaction(function()use($v,$id){$a=DB::table('citas')->where('id',$id)->lockForUpdate()->first();abort_unless($a,404);if($v['status']==='Reprogramada'){[$day,$time]=array_pad(explode('|',$v['new_slot']??'',2),2,null);if(!$day||!$time||!$this->slots()->contains(fn($s)=>$s->day===$day&&$s->time===$time))throw new \RuntimeException('Selecciona un horario disponible.');$date=Carbon::parse($day);$h=DB::table('horarios_atencion')->where('centro_id',$a->centro_id)->where('dia_semana',$date->dayOfWeekIso)->where('activo',1)->where('hora_inicio','<=',$time)->where('hora_fin','>',$time)->first();DB::table('citas')->where('id',$id)->update(['fecha'=>$day,'hora_inicio'=>$time,'hora_fin'=>Carbon::parse($day.' '.$time)->addMinutes($h->duracion_minutos)->format('H:i:s'),'horario_atencion_id'=>$h->id,'estado'=>'REAGENDADA']);}else DB::table('citas')->where('id',$id)->update(['estado'=>match($v['status']){'Cancelada'=>'CANCELADA','Pendiente'=>'PENDIENTE','Finalizada'=>'FINALIZADA',default=>'CONFIRMADA'}]);});}catch(\Illuminate\Database\QueryException|\RuntimeException $e){return back()->withErrors(['new_slot'=>'No se pudo actualizar la cita; verifica el horario.']);}return back()->with('success','Cita actualizada');}
 public function ticket($id){$a=$this->appointmentsQuery()->where('c.id',$id)->first();abort_unless($a,404);return view('ticket',compact('a'));}
 public function adminTeam(Request $r){return $this->admin('admin-team',['items'=>$this->members()->get(),'edit'=>$r->query('editar')?$this->members()->where('id',$r->query('editar'))->first():null]);}
 public function saveMember(Request $r){$v=$r->validate(['name'=>'required|string|max:150','role'=>['required',Rule::in(['ABOGADO','CONCILIADOR','DIRECTOR'])],'photo'=>'nullable|image|max:2048','description'=>'nullable|string|max:2000']);$data=['centro_id'=>$this->center()->id,'nombre_completo'=>$v['name'],'cargo'=>$v['role'],'descripcion'=>$v['description']??null];if($r->hasFile('photo')){$path='members/'.\Illuminate\Support\Str::uuid().'.'.$r->file('photo')->extension();if(!is_dir(public_path('uploads/members')))mkdir(public_path('uploads/members'),0755,true);$r->file('photo')->move(public_path('uploads/members'),basename($path));$data['fotografia']=$path;}if($r->input('id'))DB::table('equipo')->where('id',$r->input('id'))->where('centro_id',$this->center()->id)->update($data);else DB::table('equipo')->insert($data);return redirect()->route('admin.team')->with('success','Integrante guardado');}
 public function deleteMember($id){DB::table('equipo')->where('id',$id)->where('centro_id',$this->center()->id)->delete();return back()->with('success','Integrante eliminado');}
 public function adminTestimonials(Request $r){return $this->admin('admin-testimonials',['items'=>$this->reviews()->get(),'edit'=>$r->query('editar')?$this->reviews()->where('id',$r->query('editar'))->first():null]);}
 public function saveTestimonial(Request $r){$v=$r->validate(['name'=>'required|string|max:150','body'=>'required|string|max:1000']);$data=['centro_id'=>$this->center()->id,'nombre_cliente'=>$v['name'],'contenido'=>$v['body']];if($r->input('id'))DB::table('testimonios')->where('id',$r->input('id'))->where('centro_id',$this->center()->id)->update($data);else DB::table('testimonios')->insert($data);return redirect()->route('admin.testimonials')->with('success','Testimonio guardado');}
 public function toggleTestimonial($id){$t=DB::table('testimonios')->where('centro_id',$this->center()->id)->find($id);abort_unless($t,404);DB::table('testimonios')->where('id',$id)->update(['visible'=>!$t->visible]);return back()->with('success','Visibilidad actualizada');}
 public function adminContact(){return $this->admin('admin-contact');}
 public function saveContact(Request $r){$v=$r->validate(['phone'=>'required|string|max:20','email'=>'required|email|max:150','address'=>'nullable|string|max:255']);$c=$this->center();if($r->boolean('show_address') && (!$c->direccion_acreditada || empty($v['address'])))return back()->withErrors(['address'=>'La dirección debe estar acreditada antes de publicarla.']);DB::table('centros')->where('id',$c->id)->update(['telefono'=>$v['phone'],'whatsapp'=>$v['phone'],'email'=>$v['email'],'direccion'=>$v['address'],'mostrar_direccion'=>$r->boolean('show_address')]);return back()->with('success','Cambios guardados');}
 public function availability(){return $this->admin('admin-availability',['slots'=>$this->slots(),'weekly'=>DB::table('horarios_atencion')->where('centro_id',$this->center()->id)->where('activo',1)->get()]);}
 public function saveAvailability(Request $r){$v=$r->validate(['weekday'=>'required|integer|between:1,7','start'=>'required|date_format:H:i','end'=>'required|date_format:H:i']);$closed=$v['start']==='00:00' && $v['end']==='00:00';if(!$closed && ($v['end']<=$v['start'] || Carbon::parse($v['start'])->diffInMinutes(Carbon::parse($v['end']))<60))return back()->withInput()->withErrors(['end'=>'El rango debe durar al menos 60 minutos y terminar después de la hora de inicio.']);$center=$this->center();DB::transaction(function()use($v,$center,$closed){DB::table('horarios_atencion')->where('centro_id',$center->id)->where('dia_semana',$v['weekday'])->update(['activo'=>0]);if(!$closed)DB::table('horarios_atencion')->updateOrInsert(['centro_id'=>$center->id,'dia_semana'=>$v['weekday'],'hora_inicio'=>$v['start'],'hora_fin'=>$v['end']],['duracion_minutos'=>60,'activo'=>1]);});return redirect()->route('admin.availability',['dia'=>$v['weekday']])->with('success',$closed?'Día marcado como no disponible.':'Horario semanal guardado');}
 public function users(){return $this->admin('admin-users',['items'=>User::all()]);}
 public function saveUser(Request $r){$v=$r->validate(['name'=>'required|string|max:100','email'=>'required|email|unique:usuarios,email','password'=>'required|string|min:12|confirmed','access_role'=>['required',Rule::in(['ADMINISTRADOR','CONCILIADOR','RECEPCIONISTA'])]]);DB::transaction(function() use($v){$user=User::create(['nombre'=>$v['name'],'usuario'=>'admin_'.bin2hex(random_bytes(8)),'email'=>$v['email'],'password'=>Hash::make($v['password']),'rol'=>$v['access_role']==='ADMINISTRADOR'?'ADMINISTRADOR':'PERSONAL']);$user->assignRole($v['access_role']);});return back()->with('success','Administrador agregado');}
}
